import type { BulkActionResult, TableRecord } from "./types";

export interface ResolvedBulkActionResult {
  success: boolean;
  clearSelection: boolean;
  closeMenu: boolean;
  message?: string;
}

export const resolveBulkActionResult = (
  result: BulkActionResult | undefined,
  failureMessage: string,
  defaults = { clearSelection: false, closeMenu: true }
): ResolvedBulkActionResult => {
  const success = result?.success !== false;
  return {
    success,
    clearSelection:
      result?.clearSelection ??
      result?.closeMenu ??
      (success && defaults.clearSelection),
    closeMenu: result?.closeMenu ?? (success && defaults.closeMenu),
    message:
      result?.message?.trim() ||
      result?.error?.trim() ||
      (success ? undefined : failureMessage),
  };
};

export const parseBulkEditPatch = (input: string): TableRecord => {
  const patch: unknown = JSON.parse(input);
  if (patch === null || typeof patch !== "object" || Array.isArray(patch)) {
    throw new Error("Enter a valid JSON object.");
  }
  return patch as TableRecord;
};

import {
  cloneFormValue,
  fieldIsDisabled,
  fieldIsHidden,
  formValuesEqual,
} from "./form-runtime";
import type {
  FormConfig,
  FormFieldContext,
  FormFieldDefinition,
  TableRecord,
} from "./types";

const reservedFields = new Set([
  "id",
  "_id",
  "createdAt",
  "updatedAt",
  "created_at",
  "updated_at",
]);

/** Start with common values, never the first row's differing values. */
export const commonBulkValues = (rows: readonly TableRecord[]): TableRecord =>
  cloneFormValue(
    Object.fromEntries(
      Object.entries(rows[0] ?? {}).filter(([key, value]) =>
        rows.every((row) => formValuesEqual(row[key], value))
      )
    )
  );

/** Check conditional fields against every target, including explicitly changed dependencies. */
export const bulkFieldEditable = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean => {
  if (reservedFields.has(field.name) || field.bulkEdit === false) {
    return false;
  }
  const patch = Object.fromEntries(
    (context.bulkEdit?.fields ?? []).map((name) => [name, context.values[name]])
  );
  return (context.bulkEdit?.rows ?? []).every((row) => {
    const rowContext = { ...context, row, values: { ...row, ...patch } };
    return !(
      fieldIsHidden(field, rowContext) || fieldIsDisabled(field, rowContext)
    );
  });
};

/** Keep field validation, but not a full-row schema that requires untouched fields. */
export const bulkFormConfig = (
  config: FormConfig,
  context: FormFieldContext
): FormConfig => ({
  ...config,
  schema: undefined,
  submitMode: "full",
  fields: config.fields
    .filter(
      (field) =>
        context.bulkEdit?.fields.includes(field.name) &&
        bulkFieldEditable(field, context)
    )
    .map((field) => ({ ...field, hidden: false, disabled: false })),
});

/** Strip untouched fields before validation and transforms, including undeclared row metadata. */
export const bulkFormValues = (
  config: FormConfig,
  values: TableRecord
): TableRecord =>
  cloneFormValue(
    Object.fromEntries(
      config.fields.map((field) => [field.name, values[field.name]])
    )
  );

/** Invalid completion reports must never clear unrelated rows or cause a silent success. */
export const bulkCompletion = (
  ids: string[],
  result: { success: boolean; failedIds?: string[] }
): { completed: string[]; remaining: string[] } => {
  if (result.success) {
    return { completed: [...ids], remaining: [] };
  }
  const failed = result.failedIds;
  if (!failed?.length || failed.some((id) => !ids.includes(id))) {
    return { completed: [], remaining: [...ids] };
  }
  return {
    completed: ids.filter((id) => !failed.includes(id)),
    remaining: ids.filter((id) => failed.includes(id)),
  };
};

import type { ColumnPinningState, ColumnVisibilityState } from "./types";

const reserved = (id: string): boolean => id === "select" || id === "actions";
const ids = (value: unknown, allowed: string[]): string[] =>
  Array.isArray(value)
    ? [
        ...new Set(
          value.filter(
            (id): id is string =>
              typeof id === "string" && allowed.includes(id) && !reserved(id)
          )
        ),
      ]
    : [];

/** Utility columns cannot be moved, hidden, or unpinned by saved or URL state. */
export const lockedColumnOrder = (
  value: unknown,
  allowed: string[]
): string[] => [
  "select",
  ...new Set([
    ...ids(value, allowed),
    ...allowed.filter((id) => !reserved(id)),
  ]),
  "actions",
];

export const lockedColumnVisibility = (
  value: ColumnVisibilityState,
  mandatory: string[]
): ColumnVisibilityState => ({
  ...value,
  ...Object.fromEntries(
    [...mandatory, "select", "actions"].map((id) => [id, true])
  ),
});

export const lockedColumnPinning = (
  value: ColumnPinningState | undefined,
  allowed: string[],
  enabled = true
): ColumnPinningState => {
  const left = enabled ? ids(value?.left, allowed) : [];
  const right = enabled
    ? ids(value?.right, allowed).filter((id) => !left.includes(id))
    : [];
  return { left: ["select", ...left], right: [...right, "actions"] };
};

import { computed } from "vue";
import { useTableContext } from "../context";
import { applyTableQuery } from "../core";

/** Cards and the grid use the same page state; server pages must never be sliced twice. */
export const useCardRows = () => {
  const context = useTableContext();
  return computed(() => {
    if (context.data.isServer.value) {
      return context.data.rows.value;
    }
    const rows = applyTableQuery(context.data.rows.value, {
      columns: context.config.columns.definitions,
      search: context.state.search.value,
      filters: context.state.filters.value,
      advancedFilters: context.state.advancedFilters.value,
      sorting: context.state.sorting.value,
    });
    if (!context.config.table.enablePagination) {
      return rows;
    }
    const { pageIndex, pageSize } = context.state.pagination.value;
    return rows.slice(pageIndex * pageSize, (pageIndex + 1) * pageSize);
  });
};

import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import {
  cloneFormValue,
  fieldIsDisabled,
  fieldIsHidden,
} from "../form-runtime";
import type {
  FormFieldContext,
  FormFieldDefinition,
  SelectOption,
} from "../types";

/** Keep option requests scoped to the field's declared dependencies. */
export const useFieldOptions = (input: {
  field: () => FormFieldDefinition;
  context: () => FormFieldContext;
  value: () => unknown;
}) => {
  const query = ref("");
  const base = ref<SelectOption[]>([]);
  const searched = ref<SelectOption[]>([]);
  const resolved = ref<SelectOption[]>([]);
  const created = ref<SelectOption[]>([]);
  const loading = ref(false);
  const error = ref<string>();
  const mounted = ref(false);
  let baseLoaded = false;
  let generation = 0;
  let controller: AbortController | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const values = (): unknown[] => {
    const value = input.value();
    return Array.isArray(value)
      ? value
      : [value].filter(
          (item) => item !== undefined && item !== null && item !== ""
        );
  };
  const options = computed(() => {
    const configured = Array.isArray(input.field().options)
      ? (input.field().options as SelectOption[])
      : [];
    const all = [
      ...configured,
      ...base.value,
      ...searched.value,
      ...resolved.value,
      ...created.value,
    ];
    return all.filter(
      (option, index) =>
        all.findIndex((candidate) =>
          Object.is(candidate.value, option.value)
        ) === index
    );
  });
  const active = () =>
    mounted.value &&
    !fieldIsHidden(input.field(), input.context()) &&
    !fieldIsDisabled(input.field(), input.context());
  const rememberSelection = () => {
    const selected = options.value.filter((option) =>
      values().some((value) => Object.is(value, option.value))
    );
    for (const option of selected) {
      if (
        !resolved.value.some((known) => Object.is(known.value, option.value))
      ) {
        resolved.value.push(option);
      }
    }
  };
  const invalidate = () => {
    generation += 1;
    controller?.abort();
    if (timer) {
      clearTimeout(timer);
    }
    loading.value = false;
  };
  const loadBase = async (
    field: FormFieldDefinition,
    context: FormFieldContext
  ): Promise<SelectOption[]> => {
    if (baseLoaded) {
      return base.value;
    }
    const configured =
      typeof field.options === "function"
        ? await field.options(context)
        : (field.options ?? []);
    const legacy = field.optionsLoader
      ? (await field.optionsLoader()).map((value) => ({ value, label: value }))
      : [];
    return [...configured, ...legacy];
  };
  const populate = async (
    field: FormFieldDefinition,
    context: FormFieldContext,
    text: string,
    signal: AbortSignal,
    current: () => boolean
  ): Promise<void> => {
    const nextBase = await loadBase(field, context);
    if (!current()) {
      return;
    }
    base.value = nextBase;
    baseLoaded = true;
    const known = [...nextBase, ...created.value, ...resolved.value];
    const selected = values().filter(
      (value) => !known.some((option) => Object.is(value, option.value))
    );
    if (selected.length && field.resolveOptions) {
      const next = await field.resolveOptions(selected, context, signal);
      if (!current()) {
        return;
      }
      resolved.value = [...resolved.value, ...next];
    }
    if (
      field.searchOptions &&
      text.length >= Math.max(1, field.searchMinLength ?? 3)
    ) {
      const next = await field.searchOptions(text, context, signal);
      if (!current()) {
        return;
      }
      searched.value = next;
    }
  };
  const load = async (): Promise<void> => {
    invalidate();
    if (!active()) {
      return;
    }
    const version = generation;
    const request = new AbortController();
    controller = request;
    loading.value = true;
    error.value = undefined;
    const field = input.field();
    const context = {
      ...input.context(),
      values: cloneFormValue(input.context().values),
    };
    const text = query.value.trim();
    const current = () => generation === version && !request.signal.aborted;
    try {
      await populate(field, context, text, request.signal, current);
    } catch (cause) {
      if (current()) {
        error.value = cause instanceof Error ? cause.message : String(cause);
      }
    } finally {
      if (current()) {
        loading.value = false;
      }
    }
  };
  watch(
    () =>
      JSON.stringify([
        input.field().name,
        input.field().optionsScope,
        Array.isArray(input.field().options)
          ? input.field().options
          : undefined,
        (input.field().optionDependencies ?? []).map(
          (name) => input.context().values[name]
        ),
      ]),
    async () => {
      invalidate();
      baseLoaded = false;
      base.value = [];
      searched.value = [];
      resolved.value = [];
      created.value = [];
      error.value = undefined;
      query.value = "";
      await load();
    }
  );
  watch(active, async (enabled) => {
    if (enabled) {
      await load();
    } else {
      invalidate();
    }
  });
  watch(
    query,
    () => {
      invalidate();
      rememberSelection();
      searched.value = [];
      if (!(active() && query.value.trim())) {
        return;
      }
      timer = setTimeout(
        load,
        Math.max(0, input.field().searchDebounceMs ?? 300)
      );
    },
    { flush: "sync" }
  );
  watch(
    () => JSON.stringify(values()),
    async () => {
      rememberSelection();
      if (
        input.field().resolveOptions &&
        values().some(
          (value) =>
            !options.value.some((option) => Object.is(value, option.value))
        )
      ) {
        await load();
      }
    }
  );
  const reload = async () => {
    baseLoaded = false;
    await load();
  };
  onMounted(() => {
    mounted.value = true;
  });
  onBeforeUnmount(invalidate);
  return { query, options, created, loading, error, reload };
};

import { computed, nextTick, onMounted, onScopeDispose, ref } from "vue";
import { useTableContext } from "../context";
import { createLocalTableViewActions } from "../core";
import { cloneFormValue, formValuesEqual } from "../form-runtime";
import type {
  TableView,
  TableViewActionResult,
  TableViewConfig,
} from "../types";

/** Keep persistence and asynchronous state separate from menu/dialog presentation. */
export function useSavedViews(initialViews: () => TableView[]) {
  const context = useTableContext();
  const fallback = createLocalTableViewActions();
  const actions = computed(() => ({
    list: context.actions.value?.views?.list ?? fallback.list,
    create: context.actions.value?.views?.create ?? fallback.create,
    update: context.actions.value?.views?.update ?? fallback.update,
    delete: context.actions.value?.views?.delete ?? fallback.delete,
  }));
  const actionContext = {
    tableId: context.config.id,
    tableType: context.tableType,
  };
  const views = ref<TableView[]>(cloneFormValue(initialViews()));
  const active = computed(() =>
    views.value.find((view) => view.id === context.state.activeViewId.value)
  );
  const dirty = computed(() =>
    Boolean(
      active.value &&
        !formValuesEqual(
          context.state.resolveView(context.state.snapshot.value),
          context.state.resolveView(active.value.config)
        )
    )
  );
  const editable = computed(() =>
    Boolean(
      active.value &&
        !active.value.isSystem &&
        context.config.table.allowViewSave
    )
  );
  const busy = ref(false);
  const loading = ref(true);
  const loadError = ref("");
  const error = ref("");
  const dialogError = ref("");
  const dialogOpen = ref(false);
  const name = ref("");
  const shared = ref(false);
  let disposed = false;
  let hasInitialized = false;
  let initialSnapshot: TableViewConfig | undefined;
  onScopeDispose(() => {
    disposed = true;
  });
  const label = (reactKey: string, vueKey: string): string =>
    String(
      context.translations.value[reactKey] ??
        context.translations.value[vueKey] ??
        vueKey
    );
  const resultData = <T>(
    result: TableViewActionResult<T>,
    fallbackMessage: string
  ): T | undefined => {
    if (result.success === false || result.error) {
      throw new Error(result.error || fallbackMessage);
    }
    return result.data;
  };
  const select = (view?: TableView): void => {
    if (busy.value) {
      return;
    }
    error.value = "";
    if (view) {
      context.state.applyView(view.config, view.id);
    } else {
      context.state.reset();
    }
  };
  const initialize = (): void => {
    if (
      !(hasInitialized || context.state.hasInitialTableUrlState) &&
      context.state.initialViewId === context.state.activeViewId.value &&
      formValuesEqual(initialSnapshot, context.state.snapshot.value)
    ) {
      const requested = context.state.initialViewId;
      const initial = requested
        ? views.value.find((view) => view.id === requested)
        : views.value.find((view) => view.isDefault);
      if (initial) {
        select(initial);
      }
    }
  };
  const load = async (): Promise<void> => {
    loading.value = true;
    loadError.value = "";
    // Parent URL hydration finishes before testing whether the user has edited the table.
    await nextTick();
    initialSnapshot ??= cloneFormValue(context.state.snapshot.value);
    try {
      const response = await actions.value.list(actionContext);
      const loaded = Array.isArray(response)
        ? response
        : (resultData(
            response,
            label("views.notifications.error.load", "viewLoadError")
          ) ?? []);
      if (disposed) {
        return;
      }
      // Persisted records supersede initial seeds, including their renamed/configured values.
      views.value = cloneFormValue([
        ...new Map(
          [...initialViews(), ...loaded].map((view) => [view.id, view])
        ).values(),
      ]);
      initialize();
      hasInitialized = true;
    } catch (cause) {
      if (!disposed) {
        loadError.value =
          cause instanceof Error
            ? cause.message
            : label("views.notifications.error.load", "viewLoadError");
      }
    } finally {
      if (!disposed) {
        loading.value = false;
      }
    }
  };
  const openSave = (): void => {
    if (busy.value || loading.value || !context.config.table.allowViewSave) {
      return;
    }
    name.value = "";
    shared.value = false;
    dialogError.value = "";
    dialogOpen.value = true;
  };
  const closeSave = (): void => {
    if (!busy.value) {
      dialogOpen.value = false;
    }
  };
  const run = async (
    operation: () => Promise<void>,
    target: typeof error,
    fallbackMessage: string
  ): Promise<void> => {
    if (busy.value) {
      return;
    }
    busy.value = true;
    target.value = "";
    try {
      await operation();
    } catch (cause) {
      if (!disposed) {
        target.value = cause instanceof Error ? cause.message : fallbackMessage;
      }
    } finally {
      if (!disposed) {
        busy.value = false;
      }
    }
  };
  const upsert = (view: TableView): void => {
    const index = views.value.findIndex((item) => item.id === view.id);
    if (index < 0) {
      views.value.push(cloneFormValue(view));
    } else {
      views.value[index] = cloneFormValue(view);
    }
  };
  const notify = (reactKey: string, vueKey: string): void => {
    context.status.value = {
      type: "success",
      message: label(reactKey, vueKey),
    };
  };
  const save = async (): Promise<void> => {
    if (!context.config.table.allowViewSave) {
      return;
    }
    if (!name.value.trim()) {
      dialogError.value = label(
        "views.dialog.save.namePlaceholder",
        "viewNamePlaceholder"
      );
      return;
    }
    const config = cloneFormValue(context.state.snapshot.value);
    const failure = label(
      "views.notifications.error.create",
      "viewCreateError"
    );
    await run(
      async () => {
        const result = await actions.value.create({
          ...actionContext,
          name: name.value.trim(),
          config,
          isGlobal: context.config.table.allowViewSharing && shared.value,
        });
        const view = resultData(result, failure);
        if (!view) {
          throw new Error(failure);
        }
        if (disposed) {
          return;
        }
        upsert(view);
        // Preserve table edits made while persistence was pending.
        if (formValuesEqual(config, context.state.snapshot.value)) {
          context.state.applyView(view.config, view.id);
        } else {
          context.state.activeViewId.value = view.id;
        }
        dialogOpen.value = false;
        notify("views.notifications.created", "viewCreated");
      },
      dialogError,
      failure
    );
  };
  const update = async (): Promise<void> => {
    const view = active.value;
    if (!(view && editable.value && dirty.value)) {
      return;
    }
    const config = cloneFormValue(context.state.snapshot.value);
    const failure = label(
      "views.notifications.error.update",
      "viewUpdateError"
    );
    await run(
      async () => {
        const result = await actions.value.update(view.id, {
          ...actionContext,
          name: view.name,
          config,
        });
        const saved = resultData(result, failure) ?? { ...view, config };
        if (disposed) {
          return;
        }
        upsert(saved);
        if (
          context.state.activeViewId.value === view.id &&
          formValuesEqual(config, context.state.snapshot.value)
        ) {
          context.state.applyView(saved.config, saved.id);
        }
        notify("views.notifications.updated", "viewUpdated");
      },
      error,
      failure
    );
  };
  const remove = async (): Promise<void> => {
    const view = active.value;
    if (!(view && editable.value)) {
      return;
    }
    const before = cloneFormValue(context.state.snapshot.value);
    const failure = label(
      "views.notifications.error.delete",
      "viewDeleteError"
    );
    await run(
      async () => {
        resultData(await actions.value.delete(view.id, actionContext), failure);
        if (disposed) {
          return;
        }
        views.value = views.value.filter((item) => item.id !== view.id);
        if (context.state.activeViewId.value === view.id) {
          if (formValuesEqual(before, context.state.snapshot.value)) {
            context.state.reset();
          } else {
            context.state.activeViewId.value = undefined;
          }
        }
        notify("views.notifications.deleted", "viewDeleted");
      },
      error,
      failure
    );
  };
  onMounted(load);
  return {
    context,
    views,
    active,
    dirty,
    editable,
    busy,
    loading,
    loadError,
    error,
    dialogError,
    dialogOpen,
    name,
    shared,
    label,
    select,
    load,
    openSave,
    closeSave,
    save,
    update,
    remove,
  };
}

import type { QueryClient } from "@tanstack/vue-query";
import {
  type ComputedRef,
  computed,
  onScopeDispose,
  type Ref,
  ref,
  watch,
} from "vue";
import { compatibleListParams } from "../table-contracts";
import type {
  AdvancedFiltersState,
  ColumnFiltersState,
  PaginationState,
  SortingState,
  TableActions,
  TableListParams,
  TableRecord,
} from "../types";

export interface TableDataResult<TData extends TableRecord> {
  rows: Ref<TData[]>;
  rowCount: Ref<number>;
  pageCount: Ref<number>;
  isLoading: Ref<boolean>;
  error: Ref<Error | undefined>;
  isServer: ComputedRef<boolean>;
  refresh: () => Promise<void>;
}

export const useTableData = <TData extends TableRecord>({
  actions,
  inputData,
  search,
  filters,
  advancedFilters,
  sorting,
  grouping,
  pagination,
  initialRowCount,
  initialPageCount,
  queryClient,
  tableId,
  searchDebounceMs,
}: {
  actions: ComputedRef<TableActions<TData> | undefined>;
  inputData: ComputedRef<TData[]>;
  search: Ref<string>;
  filters: Ref<ColumnFiltersState>;
  advancedFilters: Ref<AdvancedFiltersState>;
  sorting: Ref<SortingState>;
  grouping: Ref<string[]>;
  pagination: Ref<PaginationState>;
  initialRowCount?: number;
  initialPageCount?: number;
  queryClient: QueryClient;
  tableId: string;
  searchDebounceMs?: Readonly<Ref<number>>;
}): TableDataResult<TData> => {
  const rows = ref<TData[]>([...inputData.value]) as Ref<TData[]>;
  const rowCount = ref(initialRowCount ?? inputData.value.length);
  const pageCount = ref(
    initialPageCount ?? Math.ceil(rowCount.value / pagination.value.pageSize)
  );
  const isLoading = ref(false);
  const error = ref<Error>();
  const isServer = computed(() => typeof actions.value?.list === "function");
  let requestId = 0;
  let activeQueryKey = "";
  let searchTimer: ReturnType<typeof setTimeout> | undefined;
  const cancelSearch = (): void => {
    clearTimeout(searchTimer);
    searchTimer = undefined;
  };
  onScopeDispose(() => {
    cancelSearch();
    requestId += 1;
  });

  const loadRows = async (): Promise<void> => {
    cancelSearch();
    if (!actions.value?.list) {
      rows.value = [...inputData.value];
      rowCount.value = inputData.value.length;
      pageCount.value = Math.ceil(rowCount.value / pagination.value.pageSize);
      return;
    }
    const currentRequest = ++requestId;
    isLoading.value = true;
    error.value = undefined;
    try {
      const params = {
        page: pagination.value.pageIndex + 1,
        pageSize: pagination.value.pageSize,
        search: search.value,
        filters: Object.fromEntries(
          filters.value.map((filter) => [filter.id, filter.value])
        ),
        advancedFilters: advancedFilters.value.filters,
        advancedFilterJoin: advancedFilters.value.joinOperator,
        sorting: sorting.value,
        grouping: grouping.value,
      };
      const list = actions.value.list;
      activeQueryKey = JSON.stringify(["yayaw-table", tableId, params]);
      const result = await queryClient.fetchQuery({
        queryKey: ["yayaw-table", tableId, params],
        queryFn: () =>
          list(compatibleListParams(params) as unknown as TableListParams),
        staleTime: 0,
      });
      if (currentRequest !== requestId) {
        return;
      }
      rowCount.value = result.meta?.totalCount ?? result.data.length;
      pageCount.value =
        result.meta?.pageCount ??
        Math.ceil(rowCount.value / pagination.value.pageSize);
      const lastPage = Math.max(0, pageCount.value - 1);
      if (pagination.value.pageIndex > lastPage) {
        // A deletion can remove the last page. Let the pagination watcher load its predecessor.
        pagination.value = { ...pagination.value, pageIndex: lastPage };
        return;
      }
      rows.value = result.data;
    } catch (cause) {
      if (currentRequest === requestId) {
        error.value = cause instanceof Error ? cause : new Error(String(cause));
      }
    } finally {
      if (currentRequest === requestId) {
        isLoading.value = false;
      }
    }
  };

  const refresh = async (): Promise<void> => {
    // A mutation must not reuse a pending list response captured before the write.
    requestId += 1;
    await queryClient.cancelQueries({
      queryKey: ["yayaw-table", tableId],
      predicate: (query) => JSON.stringify(query.queryKey) === activeQueryKey,
    });
    await loadRows();
  };

  const unsubscribe = queryClient.getQueryCache().subscribe(async (event) => {
    const key = event.query.queryKey;
    if (
      key[0] === "yayaw-table" &&
      key[1] === tableId &&
      JSON.stringify(key) === activeQueryKey &&
      event.type === "updated" &&
      event.action.type === "invalidate"
    ) {
      await refresh();
    }
  });
  onScopeDispose(unsubscribe);

  watch(
    inputData,
    async () => {
      if (!isServer.value) {
        await loadRows();
      }
    },
    { deep: true }
  );
  watch(
    [actions, search, filters, advancedFilters, sorting, grouping, pagination],
    async (current, previous) => {
      cancelSearch();
      // Invalidate in-flight results before the debounce window starts.
      requestId += 1;
      const delay = Math.max(0, searchDebounceMs?.value ?? 0);
      if (
        previous.length &&
        current[1] !== previous[1] &&
        delay &&
        isServer.value
      ) {
        searchTimer = setTimeout(loadRows, delay);
      } else {
        await loadRows();
      }
    },
    { deep: true, immediate: true }
  );

  return { rows, rowCount, pageCount, isLoading, error, isServer, refresh };
};

import {
  computed,
  onBeforeUnmount,
  onMounted,
  type Ref,
  ref,
  watch,
} from "vue";
import {
  lockedColumnOrder,
  lockedColumnPinning,
  lockedColumnVisibility,
} from "../column-locks";
import { createTableViewSnapshot } from "../core";
import { cloneFormValue } from "../form-runtime";
import {
  normalizeColumnSizing,
  normalizeFilterEnvelope,
  normalizeViewAliases,
  positiveInteger,
} from "../table-contracts";
import type {
  AdvancedFiltersState,
  ColumnFiltersState,
  ColumnPinningState,
  ColumnVisibilityState,
  PaginationState,
  SortingState,
  TableConfig,
  TableDisplayMode,
  TableGalleryViewConfig,
  TableKanbanViewConfig,
  TableRecord,
  TableViewConfig,
} from "../types";

const emptyAdvancedFilters = (): AdvancedFiltersState => ({
  filters: [],
  joinOperator: "and",
});
const emptyPinning = (): ColumnPinningState => ({
  left: ["select"],
  right: ["actions"],
});

const parseJson = <T>(value: string | null, fallback: T): T => {
  if (!value) {
    return fallback;
  }
  try {
    return JSON.parse(value) as T;
  } catch {
    try {
      return JSON.parse(decodeURIComponent(value)) as T;
    } catch {
      return fallback;
    }
  }
};

const serialize = (value: unknown): string => JSON.stringify(value);
const serializeEncoded = (value: unknown): string =>
  encodeURIComponent(JSON.stringify(value));

export interface TableStateRefs {
  search: Ref<string>;
  filters: Ref<ColumnFiltersState>;
  advancedFilters: Ref<AdvancedFiltersState>;
  sorting: Ref<SortingState>;
  visibility: Ref<ColumnVisibilityState>;
  order: Ref<string[]>;
  sizing: Ref<Record<string, number>>;
  grouping: Ref<string[]>;
  pinning: Ref<ColumnPinningState>;
  pagination: Ref<PaginationState>;
  displayMode: Ref<TableDisplayMode>;
  kanban: Ref<TableKanbanViewConfig>;
  gallery: Ref<TableGalleryViewConfig>;
  columnDragEnabled: Ref<boolean>;
  activeViewId: Ref<string | undefined>;
  initialViewId?: string;
  hasInitialTableUrlState: boolean;
  resolveView: (config: TableViewConfig) => TableViewConfig;
  snapshot: Readonly<Ref<TableViewConfig>>;
  applyView: (config: TableViewConfig, viewId?: string) => void;
  reset: () => void;
  resetFilters: () => void;
  shareableUrl: () => string;
}

export const useTableState = <TData extends TableRecord>({
  config,
  syncUrl,
  initialActiveViewId,
}: {
  config: TableConfig<TData>;
  syncUrl: boolean;
  initialActiveViewId?: string;
}): TableStateRefs => {
  const tableId = config.id;
  const columnDragStorageKey = `${tableId}-column-drag-enabled`;
  const columnDndFeatureEnabled = config.table.enableColumnDnd !== false;
  const initialColumnDragEnabled = (): boolean => {
    if (!columnDndFeatureEnabled) {
      return false;
    }
    if (typeof window === "undefined") {
      return config.table.enableColumnDragDropByDefault;
    }
    const storedPreference = window.localStorage.getItem(columnDragStorageKey);
    return storedPreference === null
      ? config.table.enableColumnDragDropByDefault
      : storedPreference === "true";
  };
  const search = ref("");
  const filters = ref<ColumnFiltersState>([]);
  const advancedFilters = ref<AdvancedFiltersState>(emptyAdvancedFilters());
  const sorting = ref<SortingState>(config.columns.sort ?? []);
  const visibility = ref<ColumnVisibilityState>(
    Object.fromEntries(
      config.columns.definitions.map((column) => [
        column.id,
        config.columns.visible.includes(column.id),
      ])
    )
  );
  const order = ref([...config.columns.order]);
  const sizing = ref<Record<string, number>>({});
  const grouping = ref<string[]>([]);
  const pinning = ref<ColumnPinningState>(emptyPinning());
  const columnIds = config.columns.definitions.map((column) => column.id);
  watch(
    [visibility, order, pinning],
    () => {
      const nextVisibility = lockedColumnVisibility(
        visibility.value,
        config.columns.mandatory
      );
      const nextOrder = lockedColumnOrder(order.value, columnIds);
      const nextPinning = lockedColumnPinning(
        pinning.value,
        columnIds,
        config.table.enableColumnPinning
      );
      if (serialize(visibility.value) !== serialize(nextVisibility)) {
        visibility.value = nextVisibility;
      }
      if (serialize(order.value) !== serialize(nextOrder)) {
        order.value = nextOrder;
      }
      if (serialize(pinning.value) !== serialize(nextPinning)) {
        pinning.value = nextPinning;
      }
    },
    { deep: true, immediate: true, flush: "sync" }
  );
  const pagination = ref<PaginationState>({
    pageIndex: 0,
    pageSize: config.table.defaultPageSize,
  });
  const displayMode = ref<TableDisplayMode>(
    config.table.defaultDisplayMode ?? "table"
  );
  const kanban = ref<TableKanbanViewConfig>({
    groupBy: config.table.kanban?.groupBy,
    titleColumn: config.table.kanban?.titleColumn,
    cardColumnIds: config.table.kanban?.cardColumnIds,
    showCardLabels: config.table.kanban?.showCardLabels,
  });
  const gallery = ref<TableGalleryViewConfig>({ ...config.table.gallery });
  const columnDragEnabled = ref(initialColumnDragEnabled());
  watch(
    columnDragEnabled,
    (enabled) => {
      const effectiveValue = columnDndFeatureEnabled && enabled;
      if (enabled !== effectiveValue) {
        columnDragEnabled.value = effectiveValue;
        return;
      }
      if (typeof window !== "undefined") {
        window.localStorage.setItem(
          columnDragStorageKey,
          String(effectiveValue)
        );
      }
    },
    { immediate: true }
  );
  // Capture the incoming URL before this table starts writing its own state.
  const initialParams = new URLSearchParams(
    syncUrl && typeof window !== "undefined" ? window.location.search : ""
  );
  const hasInitialTableUrlState = [...initialParams.keys()].some((key) =>
    key.startsWith(`${tableId}-`)
  );
  const initialViewId =
    initialParams.get("view") ??
    (hasInitialTableUrlState ? undefined : initialActiveViewId);
  const activeViewId = ref<string | undefined>(initialViewId);
  let hydrating = true;
  let urlTimer: ReturnType<typeof setTimeout> | undefined;
  const enabledFilters = (value: ColumnFiltersState): ColumnFiltersState =>
    config.table.enableColumnFilters ? value : [];
  const enabledAdvancedFilters = (
    value: AdvancedFiltersState
  ): AdvancedFiltersState =>
    config.table.enableColumnFilters
      ? (normalizeFilterEnvelope(value) as unknown as AdvancedFiltersState)
      : emptyAdvancedFilters();
  const enabledGrouping = (value: string[]): string[] =>
    config.table.enableGrouping ? value : [];
  const enabledPinning = (value: ColumnPinningState): ColumnPinningState =>
    config.table.enableColumnPinning ? value : emptyPinning();
  const enabledSizing = (value: unknown): Record<string, number> =>
    config.table.enableColumnResizing
      ? normalizeColumnSizing(value, columnIds)
      : {};
  const enabledDisplayMode = (
    requested?: TableDisplayMode
  ): TableDisplayMode =>
    requested && config.table.displayModes?.includes(requested)
      ? requested
      : (config.table.defaultDisplayMode ?? "table");

  const snapshot = computed<TableViewConfig>(() => ({
    ...createTableViewSnapshot({
      globalSearch: search.value,
      columnFilters: enabledFilters(filters.value),
      columnPinning: enabledPinning(pinning.value),
      search: search.value,
      filters: enabledFilters(filters.value),
      advancedFilters: enabledAdvancedFilters(advancedFilters.value),
      sorting: sorting.value,
      columnVisibility: visibility.value,
      columnOrder: order.value,
      columnSizing: enabledSizing(sizing.value),
      displayMode: displayMode.value,
      kanban: kanban.value,
      gallery: gallery.value,
      grouping: enabledGrouping(grouping.value),
      pinning: enabledPinning(pinning.value),
      pageSize: pagination.value.pageSize,
    }),
    // Empty grouping is intentional, even when a Kanban lane is configured.
    grouping: enabledGrouping(grouping.value),
  }));

  const fromUrl = (): void => {
    if (!syncUrl || typeof window === "undefined") {
      hydrating = false;
      return;
    }
    const params = new URLSearchParams(window.location.search);
    const defaults = resolveView({});
    search.value = params.get(`${tableId}-q`) ?? "";
    filters.value = enabledFilters(
      parseJson(params.get(`${tableId}-filters`), [])
    );
    advancedFilters.value = enabledAdvancedFilters(
      parseJson(
        params.get(`${tableId}-advancedFilters`),
        emptyAdvancedFilters()
      )
    );
    sorting.value = parseJson(
      params.get(`${tableId}-sort`),
      config.columns.sort ?? []
    );
    visibility.value = parseJson(
      params.get(`${tableId}-visibility`),
      defaults.columnVisibility ?? {}
    );
    order.value = parseJson(
      params.get(`${tableId}-order`),
      config.columns.order
    );
    sizing.value = enabledSizing(
      parseJson(params.get(`${tableId}-sizing`), {})
    );
    grouping.value = enabledGrouping(
      parseJson(params.get(`${tableId}-grouping`), [])
    );
    pinning.value = enabledPinning(
      parseJson(params.get(`${tableId}-pinning`), emptyPinning())
    );
    pagination.value = {
      pageIndex: Math.max(0, positiveInteger(params.get(`${tableId}-page`), 0)),
      pageSize: positiveInteger(
        params.get(`${tableId}-pageSize`),
        config.table.defaultPageSize
      ),
    };
    const requestedMode = params.get(
      `${tableId}-display`
    ) as TableDisplayMode | null;
    displayMode.value = enabledDisplayMode(requestedMode ?? undefined);
    kanban.value = parseJson(
      params.get(`${tableId}-kanban`),
      defaults.kanban ?? {}
    );
    if (!kanban.value.groupBy) {
      kanban.value = {
        ...kanban.value,
        groupBy:
          params.get(`${tableId}-kanbanGroupBy`) ??
          config.table.kanban?.groupBy,
      };
    }
    if (
      displayMode.value === "kanban" &&
      !params.has(`${tableId}-grouping`) &&
      (params.has(`${tableId}-kanban`) ||
        params.has(`${tableId}-kanbanGroupBy`)) &&
      kanban.value.groupBy
    ) {
      grouping.value = enabledGrouping([kanban.value.groupBy]);
    }
    gallery.value = parseJson(
      params.get(`${tableId}-gallery`),
      defaults.gallery ?? {}
    );
    activeViewId.value =
      params.get("view") ?? (hydrating ? initialViewId : undefined);
    hydrating = false;
  };

  const serializedGrouping = computed(() =>
    grouping.value.length || kanban.value.groupBy
      ? serialize(grouping.value)
      : undefined
  );
  const commitUrl = (): void => {
    const url = new URL(window.location.href);
    const set = (key: string, value: string | undefined): void =>
      value ? url.searchParams.set(key, value) : url.searchParams.delete(key);
    set(`${tableId}-q`, search.value || undefined);
    set(
      `${tableId}-filters`,
      filters.value.length ? serialize(filters.value) : undefined
    );
    set(
      `${tableId}-advancedFilters`,
      advancedFilters.value.filters.length
        ? serialize(advancedFilters.value)
        : undefined
    );
    set(
      `${tableId}-sort`,
      sorting.value.length ? serialize(sorting.value) : undefined
    );
    set(`${tableId}-visibility`, serialize(visibility.value));
    set(`${tableId}-order`, serialize(order.value));
    set(
      `${tableId}-sizing`,
      Object.keys(sizing.value).length ? serialize(sizing.value) : undefined
    );
    set(`${tableId}-grouping`, serializedGrouping.value);
    set(`${tableId}-pinning`, serializeEncoded(pinning.value));
    set(
      `${tableId}-page`,
      pagination.value.pageIndex
        ? String(pagination.value.pageIndex)
        : undefined
    );
    set(
      `${tableId}-pageSize`,
      pagination.value.pageSize !== config.table.defaultPageSize
        ? String(pagination.value.pageSize)
        : undefined
    );
    set(
      `${tableId}-display`,
      displayMode.value !== (config.table.defaultDisplayMode ?? "table")
        ? displayMode.value
        : undefined
    );
    set(
      `${tableId}-kanban`,
      Object.keys(kanban.value).length ? serialize(kanban.value) : undefined
    );
    set(
      `${tableId}-gallery`,
      Object.keys(gallery.value).length ? serialize(gallery.value) : undefined
    );
    set("view", activeViewId.value);
    window.history.replaceState(window.history.state, "", url);
  };

  const writeUrl = (): void => {
    if (!syncUrl || hydrating || typeof window === "undefined") {
      return;
    }
    if (urlTimer) {
      clearTimeout(urlTimer);
    }
    urlTimer = setTimeout(commitUrl, 40);
  };

  /** Resolve partial saved views against catalogue defaults, never the previously selected view. */
  const resolveView = (input: TableViewConfig): TableViewConfig => {
    const aliases = normalizeViewAliases(input);
    const globalSearch = String(aliases.globalSearch ?? "");
    const columnFilters = enabledFilters(
      aliases.columnFilters as ColumnFiltersState
    );
    const columnPinning = lockedColumnPinning(
      enabledPinning(aliases.columnPinning as ColumnPinningState),
      columnIds,
      config.table.enableColumnPinning
    );
    return cloneFormValue(
      createTableViewSnapshot({
        globalSearch,
        search: globalSearch,
        columnFilters,
        filters: columnFilters,
        columnPinning,
        pinning: columnPinning,
        advancedFilters: enabledAdvancedFilters(
          normalizeFilterEnvelope(
            input.advancedFilters
          ) as unknown as AdvancedFiltersState
        ),
        sorting: input.sorting ?? config.columns.sort ?? [],
        columnVisibility: lockedColumnVisibility(
          input.columnVisibility ??
            Object.fromEntries(
              config.columns.definitions.map((column) => [
                column.id,
                config.columns.visible.includes(column.id),
              ])
            ),
          config.columns.mandatory
        ),
        columnOrder: lockedColumnOrder(
          input.columnOrder ?? config.columns.order,
          columnIds
        ),
        columnSizing: enabledSizing(input.columnSizing),
        displayMode: enabledDisplayMode(input.displayMode),
        kanban: input.kanban ?? {
          groupBy: config.table.kanban?.groupBy,
          titleColumn: config.table.kanban?.titleColumn,
          cardColumnIds: config.table.kanban?.cardColumnIds,
          showCardLabels: config.table.kanban?.showCardLabels,
        },
        gallery: input.gallery ?? { ...config.table.gallery },
        grouping: enabledGrouping(
          input.grouping ??
            (enabledDisplayMode(input.displayMode) === "kanban"
              ? (aliases.grouping as string[])
              : [])
        ),
        pageSize: positiveInteger(input.pageSize, config.table.defaultPageSize),
      })
    );
  };

  const applyView = (input: TableViewConfig, viewId?: string): void => {
    const view = resolveView(input);
    search.value = view.search ?? "";
    filters.value = view.filters ?? [];
    advancedFilters.value = enabledAdvancedFilters(
      normalizeFilterEnvelope(
        view.advancedFilters
      ) as unknown as AdvancedFiltersState
    );
    sorting.value = view.sorting ?? [];
    visibility.value = view.columnVisibility ?? {};
    order.value = view.columnOrder ?? [];
    sizing.value = enabledSizing(view.columnSizing);
    displayMode.value = view.displayMode ?? "table";
    kanban.value = view.kanban ?? {};
    gallery.value = view.gallery ?? {};
    grouping.value = view.grouping ?? [];
    pinning.value = view.pinning ?? emptyPinning();
    pagination.value = {
      pageIndex: 0,
      pageSize: view.pageSize ?? config.table.defaultPageSize,
    };
    activeViewId.value = viewId;
  };

  const resetFilters = (): void => {
    search.value = "";
    filters.value = [];
    advancedFilters.value = emptyAdvancedFilters();
    pagination.value = { ...pagination.value, pageIndex: 0 };
  };

  const reset = (): void => {
    applyView({
      sorting: config.columns.sort ?? [],
      columnVisibility: Object.fromEntries(
        config.columns.definitions.map((column) => [
          column.id,
          config.columns.visible.includes(column.id),
        ])
      ),
      columnOrder: config.columns.order,
      columnSizing: {},
      displayMode: config.table.defaultDisplayMode,
      pageSize: config.table.defaultPageSize,
    });
  };

  const shareableUrl = (): string =>
    typeof window === "undefined" ? "" : window.location.href;

  watch(
    [
      search,
      filters,
      advancedFilters,
      sorting,
      visibility,
      order,
      sizing,
      grouping,
      pinning,
      pagination,
      displayMode,
      kanban,
      gallery,
      activeViewId,
    ],
    writeUrl,
    { deep: true }
  );
  watch(
    [search, filters, advancedFilters, sorting],
    () => {
      if (!hydrating && pagination.value.pageIndex !== 0) {
        pagination.value = { ...pagination.value, pageIndex: 0 };
      }
    },
    { deep: true }
  );
  onMounted(() => {
    fromUrl();
    window.addEventListener("popstate", fromUrl);
  });
  onBeforeUnmount(() => {
    if (urlTimer) {
      clearTimeout(urlTimer);
    }
    if (typeof window !== "undefined") {
      window.removeEventListener("popstate", fromUrl);
    }
  });

  return {
    search,
    filters,
    advancedFilters,
    sorting,
    visibility,
    order,
    sizing,
    grouping,
    pinning,
    pagination,
    displayMode,
    kanban,
    gallery,
    columnDragEnabled,
    activeViewId,
    initialViewId,
    hasInitialTableUrlState,
    resolveView,
    snapshot,
    applyView,
    reset,
    resetFilters,
    shareableUrl,
  };
};

import type {
  FormConfig,
  FormFieldDefinition,
  TableBehaviorConfig,
  TableConfig,
  TableDisplayMode,
  TableLayoutPreset,
  TableRecord,
} from "./types";

export const defaultTableBehavior: TableBehaviorConfig = {
  allowCreate: true,
  allowEdit: true,
  allowDuplicate: true,
  allowDelete: true,
  allowBulkEdit: true,
  allowBulkDelete: true,
  allowInlineEdit: true,
  allowViewSave: true,
  allowViewSharing: false,
  showToolbar: true,
  showToolbarHeader: true,
  showClearFilters: false,
  showResetFilters: false,
  export: true,
  bulkExport: true,
  actionsAsIcons: false,
  density: "medium",
  layoutPreset: "default",
  displayModes: ["table"],
  defaultDisplayMode: "table",
  emptyState: { show: true },
  defaultPageSize: 10,
  enableColumnDnd: true,
  enableColumnDragDropByDefault: false,
  enableColumnResizing: false,
  enableColumnFilters: true,
  enableColumnPinning: true,
  enableMultiRowSelection: true,
  enablePagination: true,
  enableRowSelection: true,
  enableRowClickEdit: false,
  enableSorting: true,
  enableViews: true,
  pageSizeOptions: [10, 20, 50, 100, 200, 500],
  inlineEdit: {
    enabled: false,
    debounceMs: 700,
    optimistic: true,
    showDelayIndicator: true,
    trigger: "doubleClickEnter",
  },
  enableCalculations: false,
  enableGrouping: true,
  enableAdvancedFilters: false,
  preserveSelectionOnQuery: false,
  searchDebounceMs: 300,
  syncUrl: true,
  dateDisplayPreset: "localized-short",
};

const layoutDefaults: Record<
  TableLayoutPreset,
  Partial<TableBehaviorConfig>
> = {
  default: {},
  admin: {
    actionsAsIcons: true,
    defaultPageSize: 20,
    density: "small",
    pageSizeOptions: [10, 20, 50, 100],
  },
  catalog: {
    actionsAsIcons: true,
    defaultPageSize: 20,
    density: "medium",
    pageSizeOptions: [10, 20, 50],
  },
  preview: {
    actionsAsIcons: true,
    defaultPageSize: 20,
    density: "small",
    pageSizeOptions: [10, 20, 50],
    showToolbarHeader: false,
  },
};

export const resolveTableDisplayModes = (
  displayModes?: TableDisplayMode[]
): TableDisplayMode[] => {
  const allowed: TableDisplayMode[] = ["table", "kanban", "gallery"];
  const unique = (displayModes ?? ["table"]).filter(
    (mode, index, modes) =>
      allowed.includes(mode) && modes.indexOf(mode) === index
  );
  return unique.length > 0 ? unique : ["table"];
};

export const defineTableConfig = <TData extends TableRecord>(
  input: Omit<TableConfig<TData>, "table"> & {
    table?: Partial<TableBehaviorConfig<TData>>;
  }
): TableConfig<TData> => {
  const preset = input.table?.layoutPreset ?? "default";
  const displayModes = resolveTableDisplayModes(input.table?.displayModes);
  const requestedMode = input.table?.defaultDisplayMode;
  const defaultDisplayMode =
    requestedMode && displayModes.includes(requestedMode)
      ? requestedMode
      : (displayModes[0] ?? "table");
  return {
    ...input,
    columns: {
      ...input.columns,
      definitions: input.columns.definitions.map((column) => ({
        ...column,
        dateDisplayPreset:
          column.type === "date"
            ? (column.dateDisplayPreset ??
              input.table?.dateDisplayPreset ??
              defaultTableBehavior.dateDisplayPreset)
            : column.dateDisplayPreset,
      })),
      sort: input.columns.sort ?? [],
      mandatory: input.columns.mandatory ?? [],
      order:
        input.columns.order.length > 0
          ? input.columns.order
          : input.columns.definitions.map((column) => column.id),
      visible:
        input.columns.visible.length > 0
          ? input.columns.visible
          : input.columns.definitions.map((column) => column.id),
    },
    table: {
      ...defaultTableBehavior,
      ...layoutDefaults[preset],
      ...input.table,
      layoutPreset: preset,
      displayModes,
      defaultDisplayMode,
      emptyState: {
        ...defaultTableBehavior.emptyState,
        ...input.table?.emptyState,
      },
      inlineEdit: {
        ...defaultTableBehavior.inlineEdit,
        ...input.table?.inlineEdit,
      },
    } as TableBehaviorConfig<TData>,
  };
};

export const defineFormConfig = <TData extends TableRecord>(
  config: FormConfig<TData>
): FormConfig<TData> => config;

type FieldOptions = Omit<FormFieldDefinition, "type">;
const fromOptions = (
  type: FormFieldDefinition["type"],
  input: FieldOptions | string,
  label?: string,
  overrides: Partial<FormFieldDefinition> = {}
): FormFieldDefinition =>
  typeof input === "string"
    ? { name: input, label: label ?? input, type, ...overrides }
    : { ...input, type };

export function createTextField(options: FieldOptions): FormFieldDefinition;
export function createTextField(
  name: string,
  label: string,
  overrides?: Partial<FormFieldDefinition>
): FormFieldDefinition;
export function createTextField(
  input: FieldOptions | string,
  label?: string,
  overrides?: Partial<FormFieldDefinition>
): FormFieldDefinition {
  return fromOptions("text", input, label, overrides);
}

export function createDateField(options: FieldOptions): FormFieldDefinition;
export function createDateField(
  name: string,
