  search?: string;
  create?: string;
  edit?: string;
  delete?: string;
  duplicate?: string;
  export?: string;
  filters?: string;
  columns?: string;
  views?: string;
  saveView?: string;
  noResults?: string;
  loading?: string;
  previous?: string;
  next?: string;
  selected?: string;
  rowsPerPage?: string;
  actions?: string;
  openActions?: string;
  options?: string;
  properties?: string;
  sort?: string;
  group?: string;
  calculations?: string;
  calculationsOn?: string;
  calculationsOff?: string;
  reset?: string;
  copyLink?: string;
  ascending?: string;
  descending?: string;
  addSort?: string;
  all?: string;
  none?: string;
  selectAll?: string;
  bulkEdit?: string;
  copy?: string;
  cancel?: string;
  confirm?: string;
}

export interface YayawTableProps<TData extends TableRecord = TableRecord> {
  tableType: string;
  tableId?: string;
  formType?: string;
  className?: string;
  config?: TableConfig<TData>;
  getTableConfig?: (tableType: string) => TableConfig<TData> | undefined;
  getTableActions?: (tableType: string) => TableActions<TData> | undefined;
  getFormConfig?: (
    formType: string,
    context?: FormFieldContext<TData>
  ) => FormConfig<TData> | undefined;
  data?: TData[];
  initialData?: TData[];
  initialRowCount?: number;
  initialPageCount?: number;
  initialViews?: TableView[];
  initialActiveViewId?: string;
  title?: string;
  description?: string;
  locale?: string;
  translations?: DataTableTranslations;
  enableAdvancedFilters?: boolean;
  enableToolbar?: boolean;
  enableViews?: boolean;
  syncUrl?: boolean;
  customBulkActions?: BulkAction<TData>[];
  searchDebounceMs?: number;
  toolbarActions?: ToolbarActionsInput<TData>;
  toolbarActionsPlacement?: ToolbarActionsPlacement;
  rowSelection?: Record<string, boolean>;
  getRowId?: (row: TData) => string;
  onRowActivate?: (row: TData, event: MouseEvent) => void;
  onRowClick?: (url: string, row: TData, event: MouseEvent) => void;
